const mongoose = require('mongoose');
const { Schema } = mongoose;

// A deviation (deficiency) raised against one SOX control in soxcontrols —
// an issue found by an audit or otherwise (management self-assessment,
// continuous controls monitoring, incident post-mortem) that has to be
// remediated. Generated by scripts/seed_sox_deviations.js for ~10% of the
// controls; every deviation names where it was found (audit name, date,
// auditor) and exactly what it affects (process, flow, task, applications,
// databases, servers, APIs) — copied from the control's real scope.
const AffectedApplicationSchema = new Schema({ name: String, appId: String, appName: String }, { _id: false });
const AffectedTaskSchema = new Schema({ diagramId: String, flowName: String, taskName: String, actor: String }, { _id: false });
const AffectedFlowSchema = new Schema({ diagramId: String, name: String, domain: String }, { _id: false });
const AffectedApiSchema = new Schema({ apiId: String, name: String, endpoint: String, method: String }, { _id: false });
const AffectedServerSchema = new Schema({ serverId: String, name: String, role: String, patchingStatus: String, backupStatus: String }, { _id: false });
const AffectedDatabaseSchema = new Schema({ softwareId: String, name: String, version: String, serverId: String }, { _id: false });

const SoxDeviationSchema = new Schema({
  deviationId: { type: String, required: true, unique: true, index: true }, // DEV-2026-0001
  controlId: { type: String, required: true, index: true },
  controlTitle: { type: String, default: '' },
  controlCategory: { type: String, default: '' },
  category: {
    type: String,
    required: true,
    enum: ['Control Not Sufficient', 'Issue Found During Audit', 'Missing Control', 'Insufficient Evidence'],
    index: true,
  },
  severity: { type: String, required: true, enum: ['Low', 'Medium', 'High'], index: true },
  // SOX classification pending aggregation with other deficiencies.
  deficiencyClassification: { type: String, enum: ['Control Deficiency', 'Significant Deficiency', 'Potential Material Weakness'], default: 'Control Deficiency' },
  deficiencyType: { type: String, enum: ['Design', 'Operating Effectiveness', 'Evidence / Documentation'], default: 'Operating Effectiveness' },
  title: { type: String, required: true },
  condition: { type: String, required: true }, // what was found
  criteria: { type: String, default: '' }, // what the control requires
  cause: { type: String, default: '' },
  effect: { type: String, default: '' }, // risk / potential misstatement
  recommendation: { type: String, default: '' },
  managementResponse: { type: String, default: '' },
  testing: {
    population: { type: String, default: '' },
    sampleSize: { type: Number, default: null },
    exceptions: { type: Number, default: null },
  },
  source: {
    type: String,
    enum: ['External Audit', 'Internal Audit', 'Management Self-Assessment', 'Continuous Controls Monitoring', 'Incident Post-Mortem'],
    required: true,
  },
  audit: {
    auditId: String,
    auditName: String,
    auditorOrganization: String,
    auditor: String, // name (role)
    auditDate: Date, // date the deviation was identified
    periodStart: Date,
    periodEnd: Date,
  },
  affected: {
    process: String, // process cycle name
    businessFlows: { type: [AffectedFlowSchema], default: [] },
    tasks: { type: [AffectedTaskSchema], default: [] },
    applications: { type: [AffectedApplicationSchema], default: [] },
    databases: { type: [AffectedDatabaseSchema], default: [] },
    servers: { type: [AffectedServerSchema], default: [] },
    apis: { type: [AffectedApiSchema], default: [] },
  },
  remediation: {
    owner: String,
    targetDate: Date,
    status: { type: String, enum: ['Open', 'In Remediation', 'Remediated — Pending Validation', 'Closed'], default: 'Open' },
    repeatFinding: { type: Boolean, default: false },
  },
  batchId: { type: String, index: true },
}, { timestamps: true, collection: 'soxdeviations' });

module.exports = mongoose.models.SoxDeviation || mongoose.model('SoxDeviation', SoxDeviationSchema);
